        self._nfe+=1
        aid=self._next_aid; self._next_aid+=1
        score=0.7 + 0.08*p.time - 0.01*(pid%3)
        unc=max(0.0,1.0-p.time)
        prev=Preview(aid,pid,p.time,score,unc)
        self.previews[aid]=prev
        p.last_preview_id=aid
        return prev
    def backward(self,anchor_id,target_time,noise_policy='fresh_noise',num_children=1,mask=None,strength=1.0):
        if anchor_id not in self.previews: raise InvalidActionError()
        ids=[]
