    survivor_set = set(survivor_ids)
    state = env.get_state()
    to_prune = [
        particle_id
        for particle_id in all_ids
        if particle_id in state.particles
        and state.particles[particle_id].status == "active"
        and particle_id not in survivor_set
    ]
    if not to_prune:
        return
    try:
        env.prune(to_prune)
